package com.smartx.com;

import com.smartx.tower.ApiClient;
import com.smartx.tower.ApiException;
import com.smartx.tower.ClientUtil;
import com.smartx.tower.TaskUtil;
import com.smartx.tower.api.MetricsApi;
import com.smartx.tower.model.*;
import java.io.IOException;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

public class App {
    public static void main(String[] args) throws ApiException, IOException {
        ApiClient client = new ApiClient();
        client.setBasePath("http://tower.smartx.com/v2/api");
        ClientUtil.login("username","root", client);

        MetricsApi metricsApi = new MetricsApi(client);
        GetClusterMetricInput params = new GetClusterMetricInput()
.range("range-string")
.clusters(new ClusterWhereInput()
.id("Cluster-id"))
.addMetricsItem("-string");
        List<WithTaskMetric> resp = metricsApi.getClusterMetrics(params);
        List<String> taskIds = resp.stream().map(withTaskObj -> withTaskObj.getTaskId()).filter(id -> Objects.nonNull(id)).collect(Collectors.toList());
        TaskUtil.WaitTasks(taskIds, client);
    }
}

package main

import (
    "context"
    "fmt"
    "time"

    "github.com/openlyinc/pointy"
    apiclient "github.com/smartxworks/cloudtower-go-sdk/v2/client"
    "github.com/smartxworks/cloudtower-go-sdk/v2/client/metrics"
    "github.com/smartxworks/cloudtower-go-sdk/v2/models"
    "github.com/smartxworks/cloudtower-go-sdk/v2/utils"
    "github.com/thoas/go-funk"
)

func main() {
    client, err := apiclient.NewWithUserConfig(apiclient.ClientConfig{
        Host:     "tower.smartx.com",
        BasePath: "v2/api",
        Schemes:  []string{"http"},
    }, apiclient.UserConfig{
        Name:     "Name",
        Password: "Password",
        Source:   models.UserSourceLOCAL,
    })
    if err != nil {
        fmt.Println(err)
        return
    }
        metrics_api := client.Metrics
    params := metrics.NewGetClusterMetricsParams()
    params.RequestBody = &models.GetClusterMetricInput{
Range: pointy.String("range-string"),
Clusters: &models.ClusterWhereInput{
ID: pointy.String("Cluster-id"),
},
Metrics: []string{"-string",
},
}
    rawResp, err := metrics_api.GetClusterMetrics(params)
    if err != nil {
        fmt.Println(err)
        return
    }
    resp := rawResp.Payload
    respTaskIds := funk.Filter(resp, func(withTaskObj *models.WithTaskMetric) bool {
        return withTaskObj.TaskID != nil
    }).([]*models.WithTaskMetric)
    if len(respTaskIds) == 0 {
        return
    }
    err = utils.WaitTasks(context.Background(), client, funk.Map(respTaskIds, func(withTaskObj *models.WithTaskMetric) string {
		return *withTaskObj.TaskID
	}).([]string), 1*time.Second)
    if err != nil {
        fmt.Println(err)
        return
    }
}

