        return
    }
        metrics_api := client.Metrics
    params := metrics.NewGetNvmfNamespaceMetricsParams()
    params.RequestBody = &models.GetNvmfNamespaceMetricInput{
NvmfNamespaces: &models.NvmfNamespaceWhereInput{
ID: pointy.String("NvmfNamespace-id"),
},
Metrics: []string{"-string",
},
Range: pointy.String("range-string"),
}
